begin;
set local search_path=public,extensions,pg_temp;
select no_plan();
select ok(not has_function_privilege('anon','public.reserve_source_upload(uuid,integer,text,text,text,text,bigint,text)','EXECUTE'),'Anonymous cannot allocate');
select ok(not has_function_privilege('authenticated','public.cleanup_source_upload(uuid,uuid,boolean)','EXECUTE'),'Browser cannot run physical cleanup bookkeeping');
select ok(not has_table_privilege('authenticated','public.assets','SELECT'),'Raw asset table stays private');
insert into auth.users(id,email) values('ab110000-0000-4000-8000-000000000001','w11-sql-a@example.invalid'),('ab110000-0000-4000-8000-000000000002','w11-sql-b@example.invalid');
update public.usage_accounts set byte_limit=500000000 where scope='global';
create temporary table fixture(result jsonb);grant all on fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ab110000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.create_project_draft('ab111000-0000-4000-8000-000000000001','create',repeat('a',64),'Upload test','software','{"sources":[]}','{}');
insert into fixture select public.reserve_source_upload('ab111000-0000-4000-8000-000000000001',1,'image-one',repeat('b',64),'test.png','image/png',100,'image');
select is((select result->'snapshot'->'project'->>'draftVersion' from fixture),'2','Allocation increments version');
select is(jsonb_array_length(public.get_draft_uploads('ab111000-0000-4000-8000-000000000001')->'items'),1,'Allocation attached to draft');
select is(public.reserve_source_upload('ab111000-0000-4000-8000-000000000001',1,'image-one',repeat('b',64),'test.png','image/png',100,'image')->>'uploadId',(select result->>'uploadId' from fixture),'Lost allocation response replays same identity despite advanced version');
select throws_ok($$select public.reserve_source_upload('ab111000-0000-4000-8000-000000000001',2,'image-one',repeat('c',64),'changed.png','image/png',100,'image')$$,'23505',null::text,'Changed payload cannot reuse key');
select throws_ok($$select public.reserve_source_upload('ab111000-0000-4000-8000-000000000001',1,'stale',repeat('c',64),'x.png','image/png',100,'image')$$,'40001',null::text,'Stale allocation conflicts');
select throws_ok($$select public.reserve_source_upload('ab111000-0000-4000-8000-000000000001',2,'invalid',repeat('c',64),'x.svg','image/svg+xml',100,'image')$$,'22023',null::text,'Unsupported MIME denied');
select throws_ok($$select public.reserve_source_upload('ab111000-0000-4000-8000-000000000001',2,'large',repeat('c',64),'x.png','image/png',5000001,'image')$$,'22023',null::text,'Oversize image denied');
select throws_ok($$select public.change_source_upload((select (result->>'uploadId')::uuid from fixture),'complete')$$,'23514',null::text,'Missing bytes are not received');
select set_config('request.jwt.claims','{"sub":"ab110000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.get_draft_uploads('ab111000-0000-4000-8000-000000000001')$$,'42501',null::text,'Foreign draft list denied');
select throws_ok($$select public.change_source_upload((select (result->>'uploadId')::uuid from fixture),'complete')$$,'42501',null::text,'Foreign receipt denied');
select throws_ok($$select public.change_source_upload((select (result->>'uploadId')::uuid from fixture),'remove')$$,'42501',null::text,'Foreign removal denied');
select throws_ok($$select public.save_project_draft('ab112000-0000-4000-8000-000000000002',0,'Attack','software',jsonb_build_object('sources',jsonb_build_array(jsonb_build_object('assetId',(select result->'snapshot'->'items'->0->>'assetId' from fixture),'role','image'))),'{}')$$,'42501',null::text,'Direct RPC cannot attach foreign source');
reset role;
select is((select reserved_bytes from public.usage_accounts where owner_id='ab110000-0000-4000-8000-000000000001'),45000000::bigint,'In-flight transfer reserves full bucket maximum');
insert into storage.objects(bucket_id,name,metadata) select 'sources',result->'snapshot'->'items'->0->>'objectKey','{"size":100,"mimetype":"image/png"}' from fixture;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ab110000-0000-4000-8000-000000000001","role":"authenticated"}',true);
reset role;
update storage.objects set metadata='{"size":99,"mimetype":"image/png"}' where bucket_id='sources' and name=(select result->'snapshot'->'items'->0->>'objectKey' from fixture);
set local role authenticated;
select throws_ok($$select public.change_source_upload((select (result->>'uploadId')::uuid from fixture),'complete')$$,'22023',null::text,'Stored byte-size mismatch cannot become received');
reset role;
update storage.objects set metadata='{"size":100,"mimetype":"image/png"}' where bucket_id='sources' and name=(select result->'snapshot'->'items'->0->>'objectKey' from fixture);
set local role authenticated;
select is(public.change_source_upload((select (result->>'uploadId')::uuid from fixture),'complete')->'items'->0->>'state','received','Matching stored metadata confirms receipt only');
select is(public.change_source_upload((select (result->>'uploadId')::uuid from fixture),'complete')->'project'->>'draftVersion','2','Receipt replay leaves content version unchanged');
reset role;
select is((select used_bytes from public.usage_accounts where owner_id='ab110000-0000-4000-8000-000000000001'),100::bigint,'Receipt charges exact stored bytes once');
select is((select reserved_bytes from public.usage_accounts where owner_id='ab110000-0000-4000-8000-000000000001'),0::bigint,'Receipt releases conservative reservation');
select is((select state from public.assets where id=(select (result->'snapshot'->'items'->0->>'assetId')::uuid from fixture)),'received','Receipt does not claim decoded validation');
set local role authenticated;
select is(jsonb_array_length(public.change_source_upload((select (result->>'uploadId')::uuid from fixture),'remove')->'items'),0,'Removal detaches selection');
select is(jsonb_array_length(public.change_source_upload((select (result->>'uploadId')::uuid from fixture),'remove')->'items'),0,'Removal replay is idempotent');
select throws_ok($$select public.change_source_upload((select (result->>'uploadId')::uuid from fixture),'complete')$$,'23514',null::text,'Removed source cannot be resurrected');
reset role;
select is((select used_bytes from public.usage_accounts where owner_id='ab110000-0000-4000-8000-000000000001'),100::bigint,'Detached bytes remain charged until confirmed physical cleanup');
select public.cleanup_source_upload((select (result->>'uploadId')::uuid from fixture),'ab110000-0000-4000-8000-000000000001',true);
select is((select used_bytes from public.usage_accounts where owner_id='ab110000-0000-4000-8000-000000000001'),0::bigint,'Privileged physical cleanup releases charge');
select public.cleanup_source_upload((select (result->>'uploadId')::uuid from fixture),'ab110000-0000-4000-8000-000000000001',true);
select is((select used_bytes from public.usage_accounts where owner_id='ab110000-0000-4000-8000-000000000001'),0::bigint,'Cleanup replay does not double release');

set local role authenticated;
update fixture set result=public.reserve_source_upload('ab111000-0000-4000-8000-000000000001',3,'shared',repeat('d',64),'shared.png','image/png',100,'image');
reset role;
insert into public.revisions(id,project_id,owner_id,revision_number,input_hash,request_kind,target_seconds,orientation,voice_profile_id,schema_version,prompt_version,composition_version)
values('ab113000-0000-4000-8000-000000000001','ab111000-0000-4000-8000-000000000001','ab110000-0000-4000-8000-000000000001',1,repeat('a',64),'initial',60,'landscape','Kore',1,'v1','v1');
insert into public.revision_assets(revision_id,asset_id,project_id,owner_id,purpose,retain_until) select 'ab113000-0000-4000-8000-000000000001',(result->'snapshot'->'items'->0->>'assetId')::uuid,'ab111000-0000-4000-8000-000000000001','ab110000-0000-4000-8000-000000000001','input',now()+interval '7 days' from fixture;
set local role authenticated;
select throws_ok($$select public.change_source_upload((select (result->>'uploadId')::uuid from fixture),'remove')$$,'23514',null::text,'Frozen revision reference prevents source destruction');
select ok(not has_function_privilege('authenticated','public.expire_source_upload(uuid)','EXECUTE'),'Browser cannot invoke operator expiry');
reset role;
delete from public.revision_assets where revision_id='ab113000-0000-4000-8000-000000000001';
delete from public.revisions where id='ab113000-0000-4000-8000-000000000001';
set local role authenticated;
select public.change_source_upload((select (result->>'uploadId')::uuid from fixture),'remove');
reset role;
select public.cleanup_source_upload((select (result->>'uploadId')::uuid from fixture),'ab110000-0000-4000-8000-000000000001',true);
select is((select used_bytes from public.usage_accounts where owner_id='ab110000-0000-4000-8000-000000000001'),45000000::bigint,'Partial transfer remains conservatively charged through authorization window');
update public.upload_allocations set created_at=now()-interval '4 days',expires_at=now()-interval '2 days' where id=(select (result->>'uploadId')::uuid from fixture);
select public.cleanup_source_upload((select (result->>'uploadId')::uuid from fixture),'ab110000-0000-4000-8000-000000000001',true);
select is((select used_bytes from public.usage_accounts where owner_id='ab110000-0000-4000-8000-000000000001'),0::bigint,'Partial charge released after bounded authorization/orphan window');
set local role authenticated;
update fixture set result=public.reserve_source_upload('ab111000-0000-4000-8000-000000000001',5,'expired',repeat('e',64),'expired.png','image/png',100,'image');
reset role;
update public.upload_allocations set created_at=now()-interval '4 days',expires_at=now()-interval '2 days' where id=(select (result->>'uploadId')::uuid from fixture);
select is(public.expire_source_upload((select (result->>'uploadId')::uuid from fixture)),true,'Operator expires abandoned allocation');
select public.cleanup_source_upload((select (result->>'uploadId')::uuid from fixture),'ab110000-0000-4000-8000-000000000001',true);
select is((select reserved_bytes+used_bytes from public.usage_accounts where owner_id='ab110000-0000-4000-8000-000000000001'),0::bigint,'Expired allocation cleanup releases quota exactly once');
select * from finish();
rollback;
